query GetWallElementWithAreaGreaterThan10(
    $exchangeId: ID!
    $elementFilter: ElementFilterInput
    $elementPagination: PaginationInput
) {
    exchange(exchangeId: $exchangeId) {
        id
        name
        elements(filter: $elementFilter, pagination: $elementPagination) {
            pagination {
                pageSize
                cursor
            }
            results {
                id
                name
                properties {
                    results {
                        name
                        value
                    }
                }
            }
        }
    }
}

